package com.cenedu.backend.domain.problem.authoring.semantic.validation;
import static org.assertj.core.api.Assertions.*;
import com.cenedu.backend.domain.problem.authoring.semantic.model.*; import com.cenedu.backend.domain.problem.authoring.generation.CurriculumScope; import java.util.*; import org.junit.jupiter.api.Test;
class ProblemSemanticModelValidatorTest { @Test void collectsCurriculumDuplicateAndMissingOperand(){var s=new CurriculumScope("2015_REVISED","MIDDLE",2,1,null,1L,"m","n","s");var m=new ProblemSemanticModelV1(1,s,new SemanticProblemIntent(null,"low",null,"S","RADIUS",1,false),List.of(new SemanticParameter("RADIUS",SemanticValueType.INTEGER,"3","cm",true,null)),List.of(new SemanticComputation("RADIUS",SemanticOperation.ADD,List.of("MISSING","RADIUS"),null,"cm","4")),List.of(),new SemanticPresentationPlan("",List.of(),List.of(),"",null,List.of()),List.of(),List.of());var e=assertThrows(SemanticValidationException.class,()->new ProblemSemanticModelValidator(new SemanticUnitAndBoundsValidator(),new SemanticConstraintValidator(),new SemanticAssertionValidator()).validate(m));assertThat(e.violations()).contains("curriculum.curriculumRevision: 2022_REVISED 이어야 합니다.","curriculum.grade: 1 이어야 합니다.","computations[0].key: RADIUS 키가 중복되었습니다.","computations[0].operands[0]: MISSING 키가 존재하지 않습니다.");} }
